Single-Page Application (SPA).diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(spa, "Single-Page Application (SPA)") {
    Component(Catalog Browser Component, "Catalog Browser Component", "React", "Allows customers to browse the secure multi-currency book catalog.")
    Component(Checkout Controller Component, "Checkout Controller Component", "React", "Manages the book checkout and payment process for shoppers.")
    Component(Recommendation UI Component, "Recommendation UI Component", "React", "Displays personalized book recommendations and reviews to customers.")
}

Rel(Catalog Browser Component, Checkout Controller Component, "Passes selected book items for purchase")
Rel(Checkout Controller Component, Recommendation UI Component, "Triggers updated recommendation fetch based on purchase history")

@enduml

API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway, "API Gateway") {
    Component(Routing_and_WAF_Controller, "Routing and WAF Controller", "Amazon API Gateway", "Handles single entry point routing, native response caching, API schema validation, and WAF protection.")
    Component(Authentication_and_Authorization_Handler, "Authentication and Authorization Handler", "Amazon Cognito & AWS WAF", "Validates JSON Web Tokens (JWT) and secures endpoints against OWASP Top-10 rules.")
}

Rel(Routing_and_WAF_Controller, Authentication_and_Authorization_Handler, "Validates incoming requests using", "")

@enduml

Aurora PostgreSQL.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(aurora_postgresql, "Aurora PostgreSQL") {
    Component(storage_engine, "PostgreSQL Storage Engine", "PostgreSQL Storage Engine", "Handles physical data storage and retrieval for transactional data.")
    Component(query_engine, "Aurora Query Processing Engine", "Aurora Query Processing Engine", "Processes and optimizes incoming SQL queries and manages transactions.")
    Component(replication_agent, "Aurora Replication Agent", "Aurora Replication Agent", "Manages data replication across Multi-AZ deployment and read replicas.")
    Component(cdc_publisher, "Logical Replication / CDC Publisher", "PostgreSQL Logical Decoding", "Streams change events asynchronously for analytics ingestion without impacting primary performance.")
}

Rel(query_engine, storage_engine, "Reads and writes transactional data", "")
Rel(replication_agent, storage_engine, "Replicates storage data across Multi-AZ and read replicas", "")
Rel(cdc_publisher, storage_engine, "Decodes WAL changes from storage", "")

@enduml

Amazon EventBridge.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(amazon_eventbridge, "Amazon EventBridge") {
    Component(Bookstore_Domain_Bus, "Bookstore Domain Bus", "AWS EventBridge Custom Bus", "Publishes asynchronous domain events such as OrderPlaced and InventoryUpdated.")
    Component(Schema_Registry___Validation, "Schema Registry & Validation", "AWS EventBridge Schema Registry", "Validates asynchronous events for consistency across decoupled services.")
}

Rel(Bookstore_Domain_Bus, Schema_Registry___Validation, "Validates event payloads against registered schemas", "HTTPS")

@enduml
